package vn.biz04.web;
import org.springframework.stereotype.Controller;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.web.bind.annotation.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.ui.Model;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.core.io.*;
import org.springframework.http.*;
import vn.biz04.data.Store;
import vn.biz04.domain.*;
import vn.biz04.service.*;
import java.math.*;
import java.time.*;
import java.security.Principal;
import java.util.*;
import java.nio.file.Path;
import java.io.IOException;
@Controller
@Transactional
public class Web {
    private final Store db;private final Access access;private final AccountService accounts;private final CatalogService catalog;private final ContractService contracts;private final PaymentService payments;private final DeliveryService delivery;private final ReviewService reviews;private final DisputeService disputes;private final TerminationService term;private final FileStore files;private final ProjectDiscovery projects;private final ProposalService proposalViews;
    public Web(Store db,Access access,AccountService accounts,CatalogService catalog,ContractService contracts,PaymentService payments,DeliveryService delivery,ReviewService reviews,DisputeService disputes,TerminationService term,FileStore files,ProjectDiscovery projects,ProposalService proposalViews){this.db=db;this.access=access;this.accounts=accounts;this.catalog=catalog;this.contracts=contracts;this.payments=payments;this.delivery=delivery;this.reviews=reviews;this.disputes=disputes;this.term=term;this.files=files;this.projects=projects;this.proposalViews=proposalViews;}
    private Long actor(Principal p){Checks.require(p!=null,"Cần đăng nhập để tiếp tục.");return access.user(db.first("from NguoiDung u where u.email=:e",NguoiDung.class,"e",p.getName()).orElseThrow(()->new BusinessException("Tài khoản không tồn tại.")).getMaNguoiDung()).getMaNguoiDung();}
    private String contractUrl(Long id){return "redirect:/hop-dong/"+id;}
    private String flash(RedirectAttributes r,String url,String msg){r.addFlashAttribute("success",msg);return url;}
    @GetMapping("/ve-sang-connect") public String about(){return "about";}
    @GetMapping("/dang-nhap") public String login(){return "login";}
    @GetMapping("/bang-dieu-khien") public String dashboard(Principal p,Model m){Long u=actor(p);NguoiDung user=db.get(NguoiDung.class,u);m.addAttribute("contracts",user.getLaQuanTriVien()?db.list("from HopDong h order by h.maHopDong desc",HopDong.class):db.list("select h from HopDong h where h.maKhachHang=:u or h.maChuyenGia=:u or (h.maKeHoach is null and exists(select y.maYeuCau from YeuCau y,DeXuat d where h.maYeuCau=y.maYeuCau and h.maDeXuat=d.maDeXuat and (y.maKhachHang=:u or d.maChuyenGia=:u))) order by h.maHopDong desc",HopDong.class,"u",u));m.addAttribute("proposals",proposalViews.sent(u));m.addAttribute("receivedProposals",proposalViews.received(u));m.addAttribute("hasCustomerRequests",db.count("select count(y) from YeuCau y where y.maKhachHang=:u","u",u)>0);m.addAttribute("myServices",db.list("from DichVu d where d.maChuyenGia=:u",DichVu.class,"u",u));return "dashboard";}
    @GetMapping("/dich-vu") public String oldServices(@RequestParam(defaultValue="")String q,RedirectAttributes r){if(!q.isEmpty())r.addAttribute("q",q);return "redirect:/trang/trangchu";}
    @GetMapping("/dich-vu/soan") public String serviceForm(Principal p,@RequestParam(required=false)Long id,Model m){Long u=actor(p);Checks.require(access.user(u).getLaChuyenGia(),"Cần vai trò chuyên gia.");DichVu d=id==null?null:db.get(DichVu.class,id);Checks.require(d==null||Objects.equals(u,d.getMaChuyenGia()),"Không sở hữu dịch vụ.");m.addAttribute("service",d);return "service-form";}
    @PostMapping("/dich-vu/luu") public String serviceSave(Principal p,@RequestParam(required=false)Long id,@RequestParam String ten,@RequestParam String linhVuc,@RequestParam String moTa,@RequestParam BigDecimal gia,RedirectAttributes r){catalog.service(actor(p),id,ten,linhVuc,moTa,gia);return flash(r,"redirect:/bang-dieu-khien","Đã lưu dịch vụ.");}
    @PostMapping("/dich-vu/{id}/hien-thi") public String serviceVisibility(Principal p,@PathVariable Long id,@RequestParam boolean hien,RedirectAttributes r){catalog.visibility(actor(p),id,hien);return flash(r,"redirect:/bang-dieu-khien","Đã cập nhật hiển thị.");}
    @GetMapping("/yeu-cau") public String requests(Principal p,Model m){Long u=actor(p);boolean admin=access.user(u).getLaQuanTriVien();m.addAttribute("requestListTitle",admin?"Yêu cầu công việc":"Yêu cầu của tôi");List<YeuCau> requests=db.list(admin?"from YeuCau y where y.trangThai='DANG_MO' or y.maKhachHang=:u order by y.maYeuCau desc":"from YeuCau y where y.maKhachHang=:u order by y.maYeuCau desc",YeuCau.class,"u",u);m.addAttribute("requests",requests);m.addAttribute("requestProposalCounts",proposalViews.counts(u,requests));return "requests";}
    @GetMapping("/yeu-cau/moi") public String requestForm(Principal p,@RequestParam(required=false)Long dichVu,Model m){actor(p);m.addAttribute("service",dichVu==null?null:db.get(DichVu.class,dichVu));return "request-form";}
    @PostMapping("/yeu-cau") public String requestSave(Principal p,@RequestParam(required=false)Long dichVu,@RequestParam String tieuDe,@RequestParam String moTa,@RequestParam BigDecimal nganSach,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate han,RedirectAttributes r){YeuCau y=catalog.request(actor(p),dichVu,tieuDe,moTa,nganSach,han);return flash(r,"redirect:/yeu-cau/"+y.getMaYeuCau(),"Đã đăng yêu cầu.");}
    @GetMapping("/yeu-cau/{id}") public String requestDetail(Principal p,@PathVariable Long id,Model m){
        Long u=actor(p);NguoiDung user=access.user(u);YeuCau y=db.get(YeuCau.class,id);boolean owner=Objects.equals(y.getMaKhachHang(),u)||user.getLaQuanTriVien();
        List<DeXuat> ds=owner?db.list("from DeXuat d where d.maYeuCau=:y",DeXuat.class,"y",id):db.list("from DeXuat d where d.maYeuCau=:y and d.maChuyenGia=:u",DeXuat.class,"y",id,"u",u);
        boolean canPropose=user.getLaChuyenGia()&&projects.eligible(y,u);
        if(!owner&&ds.isEmpty()&&!canPropose)throw new org.springframework.security.access.AccessDeniedException("Bạn không được xem yêu cầu này.");
        m.addAttribute("request",y);m.addAttribute("proposals",proposalViews.forRequest(u,id));m.addAttribute("owner",owner);m.addAttribute("canPropose",canPropose);m.addAttribute("projectDetail",!owner&&user.getLaChuyenGia());m.addAttribute("publicProject",projects.details(id,u));m.addAttribute("contract",db.first("from HopDong h where h.maYeuCau=:y",HopDong.class,"y",id).orElse(null));return "request-detail";
    }
    @PostMapping("/yeu-cau/{id}/dong") public String closeRequest(Principal p,@PathVariable Long id,RedirectAttributes r){catalog.closeRequest(actor(p),id);return flash(r,"redirect:/yeu-cau/"+id,"Đã đóng yêu cầu.");}
    @PostMapping("/yeu-cau/{id}/sua") public String editRequest(Principal p,@PathVariable Long id,@RequestParam String tieuDe,@RequestParam String moTa,@RequestParam BigDecimal nganSach,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate han,RedirectAttributes r){catalog.editRequest(actor(p),id,tieuDe,moTa,nganSach,han);return flash(r,"redirect:/yeu-cau/"+id,"Đã cập nhật yêu cầu; các đề xuất vẫn cần được đối chiếu trước khi chọn.");}
    @PostMapping("/yeu-cau/{id}/de-xuat") public String proposal(Principal p,@PathVariable Long id,@RequestParam String phuongAn,@RequestParam BigDecimal gia,@RequestParam int soNgay,RedirectAttributes r){catalog.proposal(actor(p),id,phuongAn,gia,soNgay);return flash(r,"redirect:/yeu-cau/"+id,"Đã gửi đề xuất.");}
    @PostMapping("/de-xuat/{id}/rut") public String withdraw(Principal p,@PathVariable Long id,RedirectAttributes r){catalog.withdraw(actor(p),id);return flash(r,"redirect:/bang-dieu-khien","Đã rút đề xuất.");}

    @GetMapping("/hop-dong/{id}") public String contract(Principal p,@PathVariable Long id,Model m){Long u=actor(p);HopDong h=db.get(HopDong.class,id);access.read(h,u);List<MocNghiemThu> ms=contracts.milestones(id);Map<Long,PaymentService.Balance> bs=new HashMap<>();Map<Long,List<BanGiao>> ds=new HashMap<>();Map<Long,List<GiaoDich>> gs=new HashMap<>();Map<Long,List<TranhChap>> ts=new HashMap<>();for(MocNghiemThu x:ms){Long mid=x.getMaMocNghiemThu();bs.put(mid,payments.balance(mid));ds.put(mid,db.list("from BanGiao b where b.maMocNghiemThu=:m order by b.lanBanGiao desc",BanGiao.class,"m",mid));gs.put(mid,db.list("from GiaoDich g where g.maMocNghiemThu=:m order by g.maGiaoDich desc",GiaoDich.class,"m",mid));ts.put(mid,db.list("from TranhChap t where t.maMocNghiemThu=:m order by t.maTranhChap desc",TranhChap.class,"m",mid));}
        m.addAttribute("contract",h);m.addAttribute("milestones",ms);m.addAttribute("balances",bs);m.addAttribute("deliveries",ds);m.addAttribute("transactions",gs);m.addAttribute("disputes",ts);m.addAttribute("customerId",access.customer(h));m.addAttribute("expertId",access.expert(h));m.addAttribute("isCustomer",Objects.equals(u,access.customer(h)));m.addAttribute("isExpert",Objects.equals(u,access.expert(h)));m.addAttribute("isParty",access.party(h,u));m.addAttribute("reviewEligible",reviews.eligible(h));m.addAttribute("reviewOpen",reviews.eligible(h)&&access.now().isBefore(h.getNgayKetThuc().plusDays(14)));m.addAttribute("reviewSent",db.count("select count(d) from DanhGia d where d.maHopDong=:h and d.maNguoiDanhGia=:u","h",id,"u",u)>0);m.addAttribute("reviews",reviews.publicReviews(id));m.addAttribute("terminations",db.list("from YeuCauChamDut y where y.maHopDong=:h order by y.maYeuCauChamDut desc",YeuCauChamDut.class,"h",id));m.addAttribute("electronic",h.getMaKeHoach()==null?null:contracts.electronic(u,id,h.getPhienBan()));return "contract";
    }
    @PostMapping("/hop-dong/{id}/noi-dung") public String terms(Principal p,@PathVariable Long id,@RequestParam String noiDung,@RequestParam BigDecimal tongTien,RedirectAttributes r){contracts.terms(actor(p),id,noiDung,tongTien);return flash(r,contractUrl(id),"Đã tạo phiên bản mới; các xác nhận cũ hết hiệu lực.");}
    @PostMapping("/hop-dong/{id}/moc") public String milestone(Principal p,@PathVariable Long id,@RequestParam(required=false)Long moc,@RequestParam int thuTu,@RequestParam String ten,@RequestParam String noiDung,@RequestParam String tieuChi,@RequestParam BigDecimal soTien,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate han,RedirectAttributes r){contracts.milestone(actor(p),id,moc,thuTu,ten,noiDung,tieuChi,soTien,han);return flash(r,contractUrl(id),"Đã lưu mốc và cập nhật phiên bản hợp đồng.");}
    @PostMapping("/hop-dong/{id}/moc/{mid}/xoa") public String removeMilestone(Principal p,@PathVariable Long id,@PathVariable Long mid,RedirectAttributes r){contracts.removeMilestone(actor(p),id,mid);return flash(r,contractUrl(id),"Đã xóa mốc nháp.");}
    @PostMapping("/hop-dong/{id}/xac-nhan") public String confirm(Principal p,@PathVariable Long id,@RequestParam int phienBan,RedirectAttributes r){contracts.confirm(actor(p),id,phienBan);return flash(r,contractUrl(id),"Đã ghi nhận xác nhận phiên bản.");}
    @PostMapping("/hop-dong/{id}/huy") public String cancel(Principal p,@PathVariable Long id,RedirectAttributes r){contracts.cancel(actor(p),id);return flash(r,contractUrl(id),"Đã hủy trước hiệu lực.");}
    private Long contractFor(Long mid){return db.get(MocNghiemThu.class,mid).getMaHopDong();}
    @PostMapping("/moc/{mid}/ky-quy") public String fund(Principal p,@PathVariable Long mid,@RequestParam(defaultValue="SUCCESS")String ketQua,RedirectAttributes r){GiaoDich g=payments.fund(actor(p),mid,ketQua);return flash(r,contractUrl(contractFor(mid)),"Kết quả ký quỹ: "+("THANH_CONG".equals(g.getTrangThai())?"thành công":"thất bại, tiền chưa được giữ"));}
    @PostMapping("/moc/{mid}/ban-giao") public String deliver(Principal p,@PathVariable Long mid,@RequestParam String moTa,@RequestParam(defaultValue="")String duongDan,@RequestParam(required=false)MultipartFile tep,RedirectAttributes r)throws IOException{Long u=actor(p);HopDong h=db.get(HopDong.class,contractFor(mid));access.member(h,u);Checks.require(Objects.equals(u,access.expert(h)),"Chỉ chuyên gia bàn giao.");String ref=tep!=null&&!tep.isEmpty()?files.save(tep):duongDan;delivery.deliver(u,mid,moTa,ref);return flash(r,contractUrl(h.getMaHopDong()),"Đã bàn giao; bắt đầu thời hạn phản hồi nghiệm thu 14 ngày.");}
    @PostMapping("/moc/{mid}/nghiem-thu") public String accept(Principal p,@PathVariable Long mid,@RequestParam(defaultValue="SUCCESS")String ketQua,RedirectAttributes r){boolean ok=delivery.accept(actor(p),mid,ketQua);return flash(r,contractUrl(contractFor(mid)),ok?"Đã nghiệm thu và tất toán thành công.":"Đã nghiệm thu, nhưng giao dịch thất bại. Mốc chưa tất toán.");}
    @PostMapping("/moc/{mid}/sua") public String revise(Principal p,@PathVariable Long mid,@RequestParam String lyDo,RedirectAttributes r){delivery.revise(actor(p),mid,lyDo);return flash(r,contractUrl(contractFor(mid)),"Đã gửi yêu cầu chỉnh sửa; ký quỹ vẫn được giữ.");}
    @PostMapping("/moc/{mid}/giai-ngan") public String release(Principal p,@PathVariable Long mid,@RequestParam(defaultValue="SUCCESS")String ketQua,RedirectAttributes r){boolean ok=payments.release(actor(p),mid,ketQua);return flash(r,contractUrl(contractFor(mid)),ok?"Tất toán thành công.":"Giao dịch thất bại; chưa cập nhật tất toán.");}
    @PostMapping("/hop-dong/{id}/danh-gia") public String review(Principal p,@PathVariable Long id,@RequestParam int diem,@RequestParam String noiDung,RedirectAttributes r){reviews.submit(actor(p),id,diem,noiDung);return flash(r,contractUrl(id),"Đã nhận đánh giá. Chỉ công khai khi đủ điều kiện.");}
    @PostMapping("/moc/{mid}/tranh-chap") public String openDispute(Principal p,@PathVariable Long mid,@RequestParam String lyDo,RedirectAttributes r){TranhChap t=disputes.open(actor(p),mid,lyDo);return flash(r,"redirect:/tranh-chap/"+t.getMaTranhChap(),"Đã mở tranh chấp; mốc và hợp đồng được tạm dừng xử lý thông thường.");}
    @GetMapping("/tranh-chap/{id}") public String dispute(Principal p,@PathVariable Long id,Model m){Long u=actor(p);TranhChap t=db.get(TranhChap.class,id);MocNghiemThu mid=db.get(MocNghiemThu.class,t.getMaMocNghiemThu());HopDong h=db.get(HopDong.class,mid.getMaHopDong());access.read(h,u);m.addAttribute("dispute",t);m.addAttribute("contract",h);m.addAttribute("milestone",mid);m.addAttribute("balance",payments.balance(mid.getMaMocNghiemThu()));m.addAttribute("evidence",db.list("from BangChungTranhChap b where b.maTranhChap=:t order by b.ngayGui",BangChungTranhChap.class,"t",id));m.addAttribute("isParty",access.party(h,u));return "dispute";}
    @PostMapping("/tranh-chap/{id}/bang-chung") public String evidence(Principal p,@PathVariable Long id,@RequestParam String noiDung,@RequestParam(required=false)MultipartFile tep,RedirectAttributes r)throws IOException{Long u=actor(p);TranhChap t=db.get(TranhChap.class,id);access.member(db.get(HopDong.class,contractFor(t.getMaMocNghiemThu())),u);disputes.evidence(u,id,noiDung,tep!=null&&!tep.isEmpty()?files.save(tep):null);return flash(r,"redirect:/tranh-chap/"+id,"Đã lưu bằng chứng.");}
    @PostMapping("/tranh-chap/{id}/bo-sung") public String supplement(Principal p,@PathVariable Long id,@RequestParam String noiDung,RedirectAttributes r){disputes.supplement(actor(p),id,noiDung);return flash(r,"redirect:/tranh-chap/"+id,"Đã yêu cầu bổ sung và mở hạn 5 ngày.");}
    @PostMapping("/tranh-chap/{id}/ket-luan") public String decide(Principal p,@PathVariable Long id,@RequestParam(defaultValue="")String ketLuan,@RequestParam(defaultValue="0")BigDecimal tienChuyenGia,@RequestParam(defaultValue="false")boolean tiepTuc,@RequestParam(defaultValue="SUCCESS")String ketQua,RedirectAttributes r){boolean ok=disputes.decide(actor(p),id,ketLuan,tienChuyenGia,tiepTuc,ketQua);return flash(r,"redirect:/tranh-chap/"+id,ok?"Đã thực thi kết luận và đóng hồ sơ.":"Còn giao dịch chưa thành công; hồ sơ tiếp tục mở để thử lại.");}
    @PostMapping("/hop-dong/{id}/cham-dut") public String terminate(Principal p,@PathVariable Long id,@RequestParam String lyDo,@RequestParam int tyLeChuyenGia,RedirectAttributes r){term.propose(actor(p),id,lyDo,tyLeChuyenGia);return flash(r,contractUrl(id),"Đã đề nghị chấm dứt; chờ bên còn lại xác nhận cách phân bổ.");}
    @PostMapping("/cham-dut/{id}/phan-hoi") public String respond(Principal p,@PathVariable Long id,@RequestParam boolean dongY,@RequestParam(defaultValue="SUCCESS")String ketQua,RedirectAttributes r){Long h=db.get(YeuCauChamDut.class,id).getMaHopDong();boolean ok=term.respond(actor(p),id,dongY,ketQua);return flash(r,contractUrl(h),ok?"Đã xử lý chấm dứt theo thỏa thuận.":"Chưa hoàn tất: kiểm tra trạng thái tranh chấp hoặc giao dịch cần thử lại.");}
    @GetMapping("/tep/ban-giao/{id}") public ResponseEntity<Resource> download(Principal p,@PathVariable Long id){BanGiao b=db.get(BanGiao.class,id);access.read(db.get(HopDong.class,contractFor(b.getMaMocNghiemThu())),actor(p));return attachment(b.getDuongDanSanPham());}
    @GetMapping("/tep/bang-chung/{id}") public ResponseEntity<Resource> evidenceDownload(Principal p,@PathVariable Long id){BangChungTranhChap b=db.get(BangChungTranhChap.class,id);TranhChap t=db.get(TranhChap.class,b.getMaTranhChap());access.read(db.get(HopDong.class,contractFor(t.getMaMocNghiemThu())),actor(p));return attachment(b.getDuongDanTep());}
    private ResponseEntity<Resource> attachment(String ref){Path f=files.path(ref);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(f.getFileName().toString()).build().toString()).body(new FileSystemResource(f));}
    @GetMapping("/quan-tri") public String admin(Principal p,Model m){access.admin(actor(p));m.addAttribute("users",db.list("from NguoiDung u order by u.maNguoiDung",NguoiDung.class).stream().map(u->{var view=new java.util.HashMap<>(Global.view(u));view.put("role",AdminAccounts.role(u));return view;}).toList());m.addAttribute("services",db.list("from DichVu d order by d.maDichVu desc",DichVu.class));m.addAttribute("disputes",db.list("from TranhChap t order by t.maTranhChap desc",TranhChap.class));m.addAttribute("reviews",db.list("from DanhGia d order by d.maDanhGia desc",DanhGia.class));m.addAttribute("logs",db.list("from NhatKyXuLy n order by n.maNhatKy desc",NhatKyXuLy.class).stream().limit(100).toList());return "admin";}
    @PostMapping("/quan-tri/tai-khoan/{id}") public String block(Principal p,@PathVariable Long id,@RequestParam boolean khoa,RedirectAttributes r){accounts.block(actor(p),id,khoa);return flash(r,"redirect:/quan-tri","Đã cập nhật tài khoản.");}
    @PostMapping("/quan-tri/danh-gia/{id}") public String hide(Principal p,@PathVariable Long id,@RequestParam String lyDo,RedirectAttributes r){reviews.hide(actor(p),id,lyDo);return flash(r,"redirect:/quan-tri","Đã ẩn đánh giá vi phạm.");}
}
